   340  int
   341  elf_compress (Elf_Scn *scn, int type, unsigned int flags)
   342  {
   343    if (scn == NULL)
   344      return -1;
   345
   346    if ((flags & ~ELF_CHF_FORCE) != 0)
   347      {
   348        __libelf_seterrno (ELF_E_INVALID_OPERAND);
   349        return -1;
   350      }
   351
   352    bool force = (flags & ELF_CHF_FORCE) != 0;
   353
   354    Elf *elf = scn->elf;
   355    GElf_Ehdr ehdr;
   356    if (gelf_getehdr (elf, &ehdr) == NULL)
   357      return -1;
