   438  void
   439  internal_function
   440  __libelf_set_data_list_rdlock (Elf_Scn *scn, int wrlocked)
   441  {
   442    if (scn->rawdata.d.d_buf != NULL && scn->rawdata.d.d_size > 0)
   443      {
   444        Elf *elf = scn->elf;
