   446        /* Upgrade the lock to a write lock if necessary and check
   447           nobody else already did the work.  */
   448        if (!wrlocked)
   449          {
   450            rwlock_unlock (elf->lock);
   451            rwlock_wrlock (elf->lock);
   452            if (scn->data_list_rear != NULL)
   453              return;
   454          }
