    41  static void *
    42  get_zdata (Elf_Scn *strscn)
    43  {
    44    size_t zsize, zalign;
    45    void *zdata = __libelf_decompress_elf (strscn, &zsize, &zalign);
    46    if (zdata == NULL)
    47      return NULL;
    48
    49    strscn->zdata_base = zdata;
    50    strscn->zdata_size = zsize;
    51    strscn->zdata_align = zalign;
    52
    53    return zdata;
    54  }
