   848  /* Read the next archive header.  */
   849  int
   850  internal_function
   851  __libelf_next_arhdr_wrlock (Elf *elf)
   852  {
   853    struct ar_hdr *ar_hdr;
   854    Elf_Arhdr *elf_ar_hdr;
   855
   856    if (elf->map_address != NULL)
   857      {
   858        /* See whether this entry is in the file.  */
   859        if (unlikely ((size_t) elf->state.ar.offset
   860                      > elf->start_offset + elf->maximum_size
   861                      || (elf->start_offset + elf->maximum_size
   862                          - elf->state.ar.offset) < sizeof (struct ar_hdr)))
   863          {
   864            /* This record is not anymore in the file.  */
   865            __libelf_seterrno (ELF_E_RANGE);
   866            return -1;
   867          }
   868        ar_hdr = (struct ar_hdr *) (elf->map_address + elf->state.ar.offset);
   869      }
   870    else
   871      {
   872        ar_hdr = &elf->state.ar.ar_hdr;
   873
   874        if (unlikely (pread_retry (elf->fildes, ar_hdr, sizeof (struct ar_hdr),
   875                                   elf->state.ar.offset)
   876                      != sizeof (struct ar_hdr)))
   877          {
   878            /* Something went wrong while reading the file.  */
   879            __libelf_seterrno (ELF_E_RANGE);
   880            return -1;
   881          }
   882      }
   883
   884    /* One little consistency check.  */
   885    if (unlikely (memcmp (ar_hdr->ar_fmag, ARFMAG, 2) != 0))
   886      {
   887        /* This is no valid archive.  */
   888        __libelf_seterrno (ELF_E_ARCHIVE_FMAG);
   889        return -1;
   890      }
   891
   892    /* Copy the raw name over to a NUL terminated buffer.  */
   893    *((char *) mempcpy (elf->state.ar.raw_name, ar_hdr->ar_name, 16)) = '\0';
   894
   895    elf_ar_hdr = &elf->state.ar.elf_ar_hdr;
   896
   897    /* Now convert the `struct ar_hdr' into `Elf_Arhdr'.
   898       Determine whether this is a special entry.  */
   899    if (ar_hdr->ar_name[0] == '/')
   900      {
   901        if (ar_hdr->ar_name[1] == ' '
   902            && memcmp (ar_hdr->ar_name, "/               ", 16) == 0)
   903          /* This is the index.  */
   904          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "/", 2);
   905        else if (ar_hdr->ar_name[1] == 'S'
   906                 && memcmp (ar_hdr->ar_name, "/SYM64/         ", 16) == 0)
   907          /* 64-bit index.  */
   908          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "/SYM64/", 8);
   909        else if (ar_hdr->ar_name[1] == '/'
   910                 && memcmp (ar_hdr->ar_name, "//              ", 16) == 0)
   911          /* This is the array with the long names.  */
   912          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "//", 3);
   913        else if (likely  (isdigit (ar_hdr->ar_name[1])))
   914          {
   915            size_t offset;
   916
   917            /* This is a long name.  First we have to read the long name
   918               table, if this hasn't happened already.  */
   919            if (unlikely (elf->state.ar.long_names == NULL
   920                          && read_long_names (elf) == NULL))
