   922                /* No long name table although it is reference.  The archive is
   923                   broken.  */
   924                __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   925                return -1;
   926              }
   927
   928            offset = atol (ar_hdr->ar_name + 1);
   929            if (unlikely (offset >= elf->state.ar.long_names_len))
   930              {
   931                /* The index in the long name table is larger than the table.  */
   932                __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   933                return -1;
   934              }
   935            elf_ar_hdr->ar_name = elf->state.ar.long_names + offset;
   936          }
   937        else
   938          {
   939            /* This is none of the known special entries.  */
   940            __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   941            return -1;
   942          }
   943      }
   944    else
   945      {
   946        char *endp;
   947
   948        /* It is a normal entry.  Copy over the name.  */
   949        endp = (char *) memccpy (elf->state.ar.ar_name, ar_hdr->ar_name,
   950                                 '/', 16);
   951        if (endp != NULL)
   952          endp[-1] = '\0';
   953        else
   954          {
   955            /* In the old BSD style of archive, there is no / terminator.
   956               Instead, there is space padding at the end of the name.  */
   957            size_t i = 15;
   958            do
   959              elf->state.ar.ar_name[i] = '\0';
   960            while (i > 0 && elf->state.ar.ar_name[--i] == ' ');
   961          }
   962
   963        elf_ar_hdr->ar_name = elf->state.ar.ar_name;
   964      }
   965
   966    if (unlikely (ar_hdr->ar_size[0] == ' '))
   967      /* Something is really wrong.  We cannot live without a size for
   968         the member since it will not be possible to find the next
   969         archive member.  */
   970      {
   971        __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   972        return -1;
   973      }
   974
   975    /* Since there are no specialized functions to convert ASCII to
   976       time_t, uid_t, gid_t, mode_t, and off_t we use either atol or
   977       atoll depending on the size of the types.  We are also prepared
   978       for the case where the whole field in the `struct ar_hdr' is
   979       filled in which case we cannot simply use atol/l but instead have
   980       to create a temporary copy.  */
   981
   982  #define INT_FIELD(FIELD)                                                      \
   983    do                                                                          \
   984      {                                                                         \
   985        char buf[sizeof (ar_hdr->FIELD) + 1];                                   \
   986        const char *string = ar_hdr->FIELD;                                     \
   987        if (ar_hdr->FIELD[sizeof (ar_hdr->FIELD) - 1] != ' ')                   \
   988          {                                                                     \
   989            *((char *) mempcpy (buf, ar_hdr->FIELD, sizeof (ar_hdr->FIELD)))  \
   990              = '\0';                                                           \
   991            string = buf;                                                       \
   992          }                                                                     \
   993        if (sizeof (elf_ar_hdr->FIELD) <= sizeof (long int))                    \
   994          elf_ar_hdr->FIELD = (__typeof (elf_ar_hdr->FIELD)) atol (string);     \
   995        else                                                                    \
   996          elf_ar_hdr->FIELD = (__typeof (elf_ar_hdr->FIELD)) atoll (string);    \
   997      }                                                                         \
   998    while (0)
   999
  1000    INT_FIELD (ar_date);
  1001    INT_FIELD (ar_uid);
  1002    INT_FIELD (ar_gid);
  1003    INT_FIELD (ar_mode);
  1004    INT_FIELD (ar_size);
  1005
  1006    if (elf_ar_hdr->ar_size < 0)
  1007      {
  1008        __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
  1009        return -1;
  1010      }
  1011
  1012    /* Truncated file?  */
  1013    size_t maxsize;
  1014    maxsize = (elf->start_offset + elf->maximum_size
  1015               - elf->state.ar.offset - sizeof (struct ar_hdr));
  1016    if ((size_t) elf_ar_hdr->ar_size > maxsize)
  1017      elf_ar_hdr->ar_size = maxsize;
  1018
  1019    return 0;
  1020  }
